DO $$ BEGIN RAISE EXCEPTION 'PROBE job: % | est: % | groups: %',
 (SELECT string_agg(format('%s t=%s cls=%s st=%s sold_by=%s', j.job_number, t.name, t.job_class, j.status, public._emp_name(j.sold_by_employee_id)), ';') FROM jobs j JOIN job_types t ON t.id = j.job_type_id WHERE j.job_number = '114417665' OR j.id IN (SELECT job_id FROM invoices WHERE invoice_number = '114417665')),
 (SELECT string_agg(format('%s %s by=%s earner=%s', e.estimate_number, e.status, public._emp_name(e.sold_by_employee_id), EXISTS (SELECT 1 FROM commission_rates r WHERE r.employee_id = e.sold_by_employee_id) OR EXISTS (SELECT 1 FROM commission_group_rates r WHERE r.employee_id = e.sold_by_employee_id)), ';') FROM estimates e JOIN jobs j ON j.id = e.job_id WHERE j.job_number = '114417665'),
 (SELECT string_agg(DISTINCT coalesce(g.name, 'none') || ':' || left(coalesce(pi.name, x.description), 25), ';') FROM estimates e JOIN jobs j ON j.id = e.job_id JOIN estimate_lines x ON x.estimate_option_id = e.accepted_option_id LEFT JOIN pricebook_items pi ON pi.id = x.item_id LEFT JOIN commission_groups g ON g.id = public._comm_group(x.item_id) WHERE j.job_number = '114417665'); END $$;
